{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall counting and equal groups", "look_at": {"kind": "picture", "shows": "Two plates with the same number of strawberries"}, "teaches": []},
    {"slide": 2, "does": "Introduce the learning goals", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach halves and quarters of shapes", "look_at": {"kind": "diagram", "shows": "Equal-sized squares with one half and one quarter shaded"}, "teaches": [1]},
    {"slide": 4, "does": "Correct the unequal-parts misconception", "look_at": {"kind": "picture", "shows": "Equal and unequal splits of identical rectangular cakes"}, "teaches": [1]},
    {"slide": 5, "does": "Identify shaded fractions independently", "look_at": {"kind": "diagram", "shows": "Three shapes with different numbers of equal parts"}, "teaches": [1]},
    {"slide": 6, "does": "Model finding half of 12", "look_at": {"kind": "diagram", "shows": "Twelve counters shared into two equal groups"}, "teaches": [2]},
    {"slide": 7, "does": "Try finding half of 16", "look_at": {"kind": "diagram", "shows": "Sixteen counters in two groups without count labels"}, "teaches": [2]},
    {"slide": 8, "does": "Model finding a quarter of 12", "look_at": {"kind": "diagram", "shows": "Twelve counters shared into four equal groups"}, "teaches": [3]},
    {"slide": 9, "does": "Try finding a quarter of 16", "look_at": {"kind": "diagram", "shows": "Sixteen counters in four groups without count labels"}, "teaches": [3]},
    {"slide": 10, "does": "Check what one quarter means", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 11, "does": "Practise sharing amounts independently", "look_at": {"kind": "none", "shows": null}, "teaches": [2, 3]},
    {"slide": 12, "does": "Apply fractions to new sharing problems", "look_at": {"kind": "none", "shows": null}, "teaches": [2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Count each plate. Are the groups equal?",
    "picture": {
      "shows": "Two identical plates, each holding four strawberries",
      "must_see": ["two matching plates", "four strawberries each"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        {"label": "One half", "text": "One of two equal parts."},
        {"label": "One quarter", "text": "One of four equal parts."}
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two identical squares with one half and one quarter shaded",
        "alt": "One square has one of two equal parts shaded. The other has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape": "square", "parts": 2, "cut": "vertical", "shaded": 1, "name": "1/2"},
          {"shape": "square", "parts": 4, "cut": "grid", "shaded": 1, "name": "1/4"}
        ]
      }
    },
    {
      "template": "compare",
      "heading": "Two parts are not always halves",
      "columns": [
        {
          "label": "Equal parts",
          "text": "Each piece is one half.",
          "picture": {
            "shows": "A rectangular cake cut through its centre into two equal pieces",
            "must_see": ["rectangular cake", "central straight cut", "two equal pieces"],
            "subject": "generic"
          }
        },
        {
          "label": "Unequal parts",
          "text": "These pieces are not halves.",
          "picture": {
            "shows": "An identical rectangular cake cut into one small piece and one large piece",
            "must_see": ["rectangular cake", "off-centre straight cut", "two unequal pieces"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded part",
      "lead": "Say half, quarter or neither for A, B and C.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Three shapes for pupils to identify without fraction labels",
        "alt": "A has one of four equal parts shaded. B has one of two equal parts shaded. C has two of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape": "square", "parts": 4, "cut": "grid", "shaded": 1, "name": "A"},
          {"shape": "circle", "parts": 2, "cut": "auto", "shaded": 1, "name": "B"},
          {"shape": "rectangle", "parts": 4, "cut": "vertical", "shaded": 2, "name": "C"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Find half of 12",
      "lead": "Share 12 counters into two equal groups.",
      "points": [
        "Each group has 6 counters.",
        "One half of 12 is 6."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared into two equal groups of six",
        "alt": "Two rings each contain six counters, making twelve altogether.",
        "title": null,
        "total": 12,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find half of 16",
      "lead": "Count one group. Write: One half of 16 is __.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen counters shared equally into two rings, with the group counts unknown",
        "alt": "Sixteen counters are shared equally between two rings. Find the number in one ring.",
        "title": null,
        "total": 16,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": true
      }
    },
    {
      "template": "visual-text",
      "heading": "Find a quarter of 12",
      "lead": "Share 12 counters into four equal groups.",
      "points": [
        "Each group has 3 counters.",
        "One quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared into four equal groups of three",
        "alt": "Four rings each contain three counters, making twelve altogether.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find a quarter of 16",
      "lead": "Count one group. Write: One quarter of 16 is __.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen counters shared equally into four rings, with the group counts unknown",
        "alt": "Sixteen counters are shared equally between four rings. Find the number in one ring.",
        "title": null,
        "total": 16,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": true
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the answer",
      "stem": "What is one quarter of 8 counters?",
      "options": ["4 counters", "2 counters", "8 counters"],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Draw and share",
      "questions": [
        "Find one half of 10 counters.",
        "Find one quarter of 4 counters.",
        "Find one quarter of 20 counters."
      ],
      "instruction": "Draw equal groups. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Solve the sharing problems",
      "questions": [
        "Mia gives away half of 18 beads. How many?",
        "Share 8 buns equally on 4 plates. How many on each?",
        "Sam has 20 beads. Find half, then half of that."
      ],
      "instruction": "Draw your groups. Explain your answers.",
      "picture": null
    }
  ]
}
